372:     }
373:     // Express 3 and lower
374:     else {
375:       cpOptsInData(data, opts);
376:     }
377:   }
378:   opts.filename = filename;
379: 
380:   try {
381:     result = handleCache(opts)(data);
382:   }
383:   catch(err) {
384:     return cb(err);
385:   }
386:   return cb(null, result);
